import{_ as o,a0 as p,w as i,s as l,ao as d,I as s,x as e,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"命令行星期二——第六部分 | LCTT x X-CMD","titleTemplate":false,"description":"命令行星期二——第六部分 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行星期二——第六部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行星期二——第六部分 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140731 Command Line Somedays--Part Six","title":"命令行星期二——第六部分","tag":"201408","desc":""},"relativePath":"201408/20140731 Command Line Somedays--Part Six.md","filePath":"[post].md"}'),m={name:"201408/20140731 Command Line Somedays--Part Six.md"};function x(h,t,u,f,g,C){const a=p("Link");return i(),l("div",null,[t[13]||(t[13]=d(`<h1 id="命令行星期二——第六部分" tabindex="-1">命令行星期二——第六部分 <a class="header-anchor" href="#命令行星期二——第六部分" aria-label="Permalink to “命令行星期二——第六部分”">​</a></h1><p>不管怎样，让我们继续我们今天的日程吧：输入/输出重定向。</p><p>我们已经用过的大多数命令，都把他们的结果张贴到了终端显示中。然而，我们也可以让这些命令的显示放进一个文件、设备中，或者作为其它命令的输入，一切都在<strong>重定向</strong>。</p><h3 id="标准输出" tabindex="-1">标准输出 <a class="header-anchor" href="#标准输出" aria-label="Permalink to “标准输出”">​</a></h3><p>那么，命令行程序主要是怎么工作的呢？它们会将命令的结果丢给一个叫做标准输出的设备，然后，标准输出会将这些结果发送到你的显示设备上，这样你就可以畅快地阅读这些信息了。然而，你也可以让命令的结果显示到一个文本文件中，像这样，用“&gt;”字符（我的例子）：</p><pre><code>man zypper &gt; man.txt
</code></pre><p>这儿我所干的是， 我想要获得zypper的一个帮助页。但是，我想要把它放到一个文本文件中去，因而我可以在我需要他们的时候（例如，在论坛、IRC寻求帮助时）很方便地读取这些结果。所以，这个命令做的是，保存man zypper输出结果到我的家目录中的man.txt，这样你可以看到，我可以用gedit来打开它：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Zaslonska-slika-2014-07-30-103144.png" alt=""></p><p>如果我重复了该命令，或者使用不同的命令重定向到了同名文件，那么它就会被一次又一次地覆盖。所以，在那种情况下，如果我想要把输出结果重定向并附加到现存文件中，我唯一能做的事情就是下一次使用“&gt;&gt;”来替换“&gt;”。</p><h3 id="标准输入" tabindex="-1">标准输入 <a class="header-anchor" href="#标准输入" aria-label="Permalink to “标准输入”">​</a></h3><p>许多命令也可以接受来自称之为标准输入的设备的输入。默认情况下，输入来自键盘，然而也可以来自一个文件。要重定向它，使用跟前面相反的字符：‘<strong>&lt;</strong>’。</p><p>请看下面的例子：</p><pre><code>sort &lt; man.txt
</code></pre><h3 id="管道" tabindex="-1">管道 <a class="header-anchor" href="#管道" aria-label="Permalink to “管道”">​</a></h3><p>要想把多个命令连接到一起，你可以使用管道。管道所要做的是，将一个命令的标准输出注入到另一个命令的标准输入。肖茨先生的最爱：</p><pre><code>ls – l | less
</code></pre><p>通过使用‘| less’这个小把戏，你可以让任何命令滚动输出。 过滤器</p><h3 id="过滤器" tabindex="-1">过滤器 <a class="header-anchor" href="#过滤器" aria-label="Permalink to “过滤器”">​</a></h3><p>过滤器是管道中常用的程序。过滤器获取标准输入，对它进行操作，然后把结果发送到标准输出。它们可以以一种相当强大的方式处理信息。这儿提供了一个程序列表，大多数都是用作过滤器的。它们可以用于执行、查询，或者将帮助页重定向到它们，然后再重定向到一个文件！</p><p>过滤器：sort, uniq, grep （我们发现这一个东西遍布论坛，因此我建议大家深入研究一下）, fmt, pr, head, tail, tr, sed, awk。</p><h3 id="结束" tabindex="-1">结束 <a class="header-anchor" href="#结束" aria-label="Permalink to “结束”">​</a></h3><p>我们只剩下几个课程来阐述CLI的基本用法了，到成熟期的时候，我希望大家都会对CLI兴趣会增多一点了，也希望大家在萧条期也进行一些探索！而在你们动手干的时候，我希望你们…… <strong>玩得不亦乐乎！</strong></p><hr>`,23)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),n(a,{href:"https://news.opensuse.org/2014/07/30/command-line-somedays-part-six/"},{default:r(()=>[...t[0]||(t[0]=[e("https://news.opensuse.org/2014/07/30/command-line-somedays-part-six/",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=e("作者：",-1)),n(a,{href:"https://news.opensuse.org/author/holden87/"},{default:r(()=>[...t[2]||(t[2]=[e("Nenad Latinović",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),n(a,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[3]||(t[3]=[e("GOLinux",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),n(a,{href:"http://linux.cn/"},{default:r(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const P=o(m,[["render",x]]);export{b as __pageData,P as default};
